* {
    padding: 0;
    margin: 0;
    box-sizing: border-box;
}

.mx {
    width: 500px;
    margin: 0 auto;
}

th,
td {
    color: black;
}

.main_logo {
    display: flex;
    justify-content: space-evenly;
    align-items: center;
    border-bottom: 1px solid gray;
    margin: 0px 10px;
}

.logo_left img {
    width: 300px;
    height: 100px;
}

.right_logo h4 {
    text-align: center;
}

/* Main information */
.mian_info {
    display: flex;
    width: 100%;
    justify-content: space-around;
    padding-top: 10px;
}

.info_2 {
    margin-left: 100px;
}

.info_id,
.info_age,
.info_doctor {
    display: flex;
}

.info_id_2,
.info_age_2,
.info_doctor_2 {
    display: flex;
}

.info_id h4 {
    color: #9478a9;
    padding-left: 100px;
}

.info_age h4 {
    color: #9478a9;
    padding-left: 90px;
}

.info_doctor h4 {
    color: #9478a9;
    padding-left: 64px;
}

.info_id_2 h4 {
    color: #9478a9;
    padding-left: 100px;
}

.info_age_2 h4 {
    color: #9478a9;
    padding-left: 127px;
}

.info_doctor_2 h4 {
    color: #9478a9;
    padding-left: 117px;
}

.info_id h3,
.info_age h3,
.info_doctor h3 {
    color: #153b50;
}

/* Tables */
.table_section {
    width: 100%;
    padding-top: 0;
    margin: 0;
}

table {
    width: 100%;
    border-collapse: collapse;
}

table th,
table td {
    border-bottom: 1px solid gray;
    border-top: 1px solid gray;
    padding: 5px;
    line-height: 1.2;
}

th {
    color: black;
    font-size: 14px;
    font-weight: bold;
}

table th {
    text-align: left;
    color: gray;
    font-size: 14px;
    font-weight: bold;
}

/* Footer */
.signature {
    display: flex;
    justify-content: center;
    height: 100px;
    align-items: center;
    color: #342042;
}

.bukanka {
    display: flex;
    justify-content: center;
    color: #3e30c2;
    border-bottom: 2px dotted #1c146b;
    padding: 10px 0;
}

.days {
    color: red;
}

.address {
    display: flex;
    justify-content: center;
    padding-top: 20px;
    color: #342042;
}

.address h4 {
    font-size: 14px;
}

.address h4 span {
    padding: 0 5px;
}

/* Page break */
.page-break {
    page-break-before: always;
    break-before: page;
}

